class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        visited = [False] * (n * n + 1)
        queue = [(1, 0)]  # (square, rolls)
        while queue:
            square, rolls = queue.pop(0)
            if square == n * n:
                return rolls
            for next_square in range(square + 1, min(square + 7, n * n + 1)):
                if visited[next_square]:
                    continue
                visited[next_square] = True
                r, c = (next_square - 1) // n, (next_square - 1) % n
                if board[n - 1 - r][c if n % 2 == 1 else n - 1 - c] != -1:
                    queue.append((board[n - 1 - r][c if n % 2 == 1 else n - 1 - c], rolls + 1))
