class Solution:
    def recoverFromPreorder(self, traversal: str) -> Optional[TreeNode]:
        nodes = []
        for node in traversal.split('-'):
            if node:
                nodes.append(int(node))

        def dfs(depth, idx):
            if idx >= len(nodes):
                return None, idx
            node = TreeNode(nodes[idx])
            idx += 1
            if depth == 0:
                node.left, idx = dfs(1, idx)
                node.right, idx = dfs(1, idx)
            else:
                node.left, idx = dfs(depth + 1, idx)
                if idx < len(nodes):
                    node.right, idx = dfs(depth + 1, idx)
            return node, idx

        root, _ = dfs(0, 0)
        return root

