class Solution:
    def minimum_travel_time(self, n: int, m: int, a: int, b: int, roads: List[Tuple[int, int, int]]) -> List[int]:
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                if rank[root_x] > rank[root_y]:
                    parent[root_y] = root_x
                else:
                    parent[root_x] = root_y
                    if rank[root_x] == rank[root_y]:
                        rank[root_y] += 1

        roads.sort(key=lambda x: x[2])
        res = [0] * n
        for u, v, c in roads:
            if find(u) != find(v):
                union(u, v)
                if c == a:
                    res[v - 1] = res[u - 1] + a
                else:
                    res[v - 1] = res[u - 1] + b
        return res

