class Solution:
    def max_city_score(self, n: int, m: int, scores: List[int], roads: List[Tuple[int, int]], start: int) -> int:
        graph = [[] for _ in range(n + 1)]
        for u, v in roads:
            graph[u].append(v)
            graph[v].append(u)

        dp = [[-1] * (1 << (n + 1)) for _ in range(n + 1)]

        def dfs(node: int, mask: int) -> int:
            if dp[node][mask] != -1:
                return dp[node][mask]
            res = 0
            for neighbor in graph[node]:
                if not (mask & (1 << neighbor)):
                    res = max(res, dfs(neighbor, mask | (1 << neighbor)) + scores[neighbor - 1])
            dp[node][mask] = res
            return res

        return dfs(start, 1 << start) + scores[start - 1]

