        def dfs(node, parent, depth, max_depth):
            if depth > max_depth[0]:
                max_depth[0] = depth
                max_depth[1] = node
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    dfs(neighbor, node, depth + weight, max_depth)

        max_depth = [0, 0]
        dfs(1, 0, 0, max_depth)
        max_node = max_depth[1]

        max_depth = [0, 0]
        dfs(max_node, 0, 0, max_depth)
        diam = max_depth[0]

        res = 0
        for i in range(1, n + 1):
            cnt = 0
            for j in range(1, n + 1):
                if i != j:
                    max_depth = [0, 0]
                    dfs(j, 0, 0, max_depth)
                    if max_depth[0] == diam:
                        cnt += 1
            res = max(res, min(cnt, usage[i - 1]))

        return diam - res + 1
